with open('/logs/agent/opencode.txt', 'rb') as f:
    data = f.read().decode('utf-8', errors='ignore')

# find occurrences of 64-line screens
lines = data.split('\n')
screens = []
curr = []
for l in lines:
    if len(l) == 64 and all(c in '0123456789abcdef' for c in l):
        curr.append(l)
        if len(curr) == 64:
            screens.append(curr)
            curr = []
    else:
        curr = []

print('Total 64x64 screens:', len(screens))

# Filter for Level 2 screens (row 3 starts with '330aa')
l2_screens = [s for s in screens if s[3].startswith('330aa')]
print('Level 2 screens:', len(l2_screens))

for idx, s in enumerate(l2_screens):
    # check where P, diamond, box, goal are
    p_pos = None
    diamond_pos = None
    box_pos = None
    goal_pos = None
    for r in range(10):
        for c in range(11):
            sub = [s[10 + r*5 + dr][4 + c*5 : 4 + (c+1)*5] for dr in range(5)]
            flat = ''.join(sub)
            if 'c' in flat: p_pos = (r, c)
            if '8' in flat:
                if '00800' in sub[0]: diamond_pos = (r, c)
                elif '88888' in sub[0]: box_pos = (r, c)
            if '3' in flat and (r, c) != (0, 0):
                goal_pos = (r, c)
    timer = s[0].count('4')
    print(f'L2 #{idx:2d}: timer={timer:2d}, P={p_pos}, Diamond={diamond_pos}, Box={box_pos}, Goal={goal_pos}')
"

