with open('/logs/agent/opencode.txt', 'r', errors='ignore') as f:
    text = f.read()

# Let's search for 330aa
import re
for m in re.finditer(r'330aa', text):
    start = max(0, m.start() - 200)
    end = min(len(text), m.end() + 2000)
    lines = text[start:end].replace('\\n', '\n').split('\n')
    valid = [l.strip() for l in lines if len(l.strip()) == 64]
    if len(valid) >= 60:
        print('Found valid screen with 64 lines!')
        # find index of row starting with 330aa
        for i, l in enumerate(valid):
            if l.startswith('330aa'):
                base = i - 3
                grid = []
                for r in range(10):
                    row_types = []
                    for c in range(11):
                        cell = [valid[base + 10 + r*5 + dr][4 + c*5 : 4 + (c+1)*5] for dr in range(5)]
                        if cell[0] == '55555':
                            row_types.append('#')
                        else:
                            row_types.append('.')
                    grid.append(''.join(row_types))
                for r in range(10):
                    print(f'{r}: {grid[r]}')
                break
        break
